<template>
  <div class="cluster-show">
    <loading-screen :is-loading="isLoading || isDeleting"></loading-screen>

    <a-layout>
      <a-layout style="padding: 7px 30px">
        <div class="wrapper">
          <a-page-header
            v-if="cluster"
            :title="cluster.name"
            @back="backToAllClusters"
          >
            <template slot="extra">
              <a-button
                type="primary"
                icon="plus"
                @click.prevent="() => toggleSidebar()"
                >Add Order
              </a-button>
            </template>
          </a-page-header>

          <div v-if="cluster">
            <!-- Graphs -->
            <div class="cluster-graphs-wrapper">
              <cluster-graphs
                :key="reloadKey"
                :graph-reload-key="graphReloadKey"
                :cluster-id="cluster['_id']"
              ></cluster-graphs>
            </div>
            <!-- / Graphs -->

            <!-- Orders & Insights -->
            <a-tabs>
              <a-tab-pane tab="All Orders">
                <cluster-orders-table
                  :key="reloadKey"
                  :cluster-id="cluster['_id']"
                  @record-selected="(record) => viewInsightsFor(record)"
                  @remove-order="removeOrder"
                ></cluster-orders-table>
              </a-tab-pane>
            </a-tabs>
            <!-- / Orders & Insights -->
          </div>
        </div>
      </a-layout>
      <a-layout-sider
        :width="sidebarType === 'add-order' ? 400 : 500"
        theme="dark"
        :style="{ background: '#f7fafc', borderLeft: '1px solid #e3e8ee' }"
        :collapsed-width="0"
        v-model="shouldHideSidebar"
        :trigger="null"
        collapsible
      >
        <sidebar
          v-if="shouldShowSidebar && sidebarType === 'add-order'"
          @close="() => toggleSidebar()"
          @reload="incrementReloadKey"
          :cluster-id="cluster['_id']"
        ></sidebar>

        <insights-sidebar
          v-if="shouldShowSidebar && sidebarType === 'insights'"
          @close="() => toggleSidebar('insights')"
          @reload="incrementReloadKey"
          :cluster-id="cluster['_id']"
          :erp-order-id="selectedErpOrderId"
          :insights="insights"
        ></insights-sidebar>
      </a-layout-sider>
    </a-layout>
  </div>
</template>

<script>
import axios from "axios";
import ClusterOrdersTable from "./Show/ClusterOrdersTable";
import ClusterGraphs from "./Show/ClusterGraphs.vue";
import Sidebar from "./Show/Sidebar.vue";
import InsightsSidebar from "./Show/InsightsSidebar";

const _ = require("lodash");

export default {
  name: "Show",
  components: {
    InsightsSidebar,
    ClusterOrdersTable,
    ClusterGraphs,
    Sidebar,
  },
  created() {
    this.loadCluster(this.$route.params.id);
  },
  data() {
    return {
      cluster: null,
      reloadKey: 1,
      graphReloadKey: 1,
      shouldShowSidebar: false,
      sidebarType: "add-order",
      selectedErpOrderId: null,
      isDeleting: false,

      insights: [],
      isLoadingInsights: false,
    };
  },
  computed: {
    shouldHideSidebar() {
      return !this.shouldShowSidebar;
    },
  },
  watch: {
    $route() {
      this.loadCluster(this.$route.params.id);
    },
  },
  methods: {
    backToAllClusters() {
      this.$router.push("/intelligence/clusters");
    },

    toggleSidebar(sidebarType = "add-order") {
      let vm = this;

      if (sidebarType !== this.sidebarType) {
        console.log(sidebarType);
        console.log(this.sidebarType);
        this.sidebarType = sidebarType;
        if (!this.shouldShowSidebar) {
          this.shouldShowSidebar = true;
        }
        window.setTimeout(() => {
          vm.graphReloadKey += 1;
        }, 250);
        return false;
      }

      this.shouldShowSidebar = !this.shouldShowSidebar;
      window.setTimeout(() => {
        vm.graphReloadKey += 1;
      }, 250);
    },

    viewInsightsFor(record) {
      let vm = this;

      this.sidebarType = "insights";
      this.selectedErpOrderId = record["_id"];

      if (!this.shouldShowSidebar) {
        this.shouldShowSidebar = true;
      }

      window.setTimeout(() => {
        vm.graphReloadKey += 1;
      }, 250);
    },

    loadCluster(id) {
      let vm = this;
      vm.cluster = null;
      vm.insights = [];
      vm.isLoading = true;
      axios
        .get(window.API_BASE + "/intelligence/clusters/" + id)
        .then((r) => {
          vm.isLoading = false;
          vm.cluster = r.data;
          vm.loadInsights();
        })
        .catch((e) => {
          vm.isLoading = false;
          vm.$message.error("Error loading cluster");
          console.log(e);

          let errors;
          if (
            e.response &&
            e.response.data &&
            typeof e.response.data === "object"
          ) {
            errors = _.flatten(_.toArray(e.response.data.errors));
          } else {
            errors = ["Something went wrong. Please try again."];
          }
          vm.serverErrors = errors;
        });
    },

    loadInsights() {
      let vm = this;
      vm.insights = [];
      vm.isLoadingInsights = true;
      axios
        .get(
          window.API_BASE +
            "/intelligence/clusters/" +
            vm.cluster["_id"] +
            "/insights"
        )
        .then((r) => {
          vm.isLoadingInsights = false;
          vm.insights = r.data;
        })
        .catch((e) => {
          vm.isLoadingInsights = false;
          vm.$message.error("Error loading insights");
          console.log(e);

          let errors;
          if (
            e.response &&
            e.response.data &&
            typeof e.response.data === "object"
          ) {
            errors = _.flatten(_.toArray(e.response.data.errors));
          } else {
            errors = ["Something went wrong. Please try again."];
          }
          vm.serverErrors = errors;
        });
    },

    incrementReloadKey() {
      this.reloadKey += 1;
    },

    removeOrder(order) {
      let vm = this;
      vm.isDeleting = true;
      axios
        .post(
          window.API_BASE +
            "/intelligence/clusters/" +
            this.cluster["_id"] +
            "/remove-order",
          {
            erp_order_id: order["_id"],
          }
        )
        .then(() => {
          vm.isDeleting = false;
          vm.$message.success("Order removed successfully");
          vm.loadCluster(this.cluster["_id"]);
        })
        .catch((e) => {
          console.log(e);
          vm.isDeleting = false;
          vm.$message.error("Error removing order");
        });
    },
  },
};
</script>

<style scoped>
.cluster-show {
  height: 100%;
}

.wrapper {
  max-height: 100%;
  overflow-y: scroll;
}

.cluster-graphs-wrapper {
  margin-bottom: 20px;
}
</style>